// TestConvertPosterGraphQLFallback pins the poster fallback (artwork
// 2026-10-27): shikimori's REST image is a FALSE NEGATIVE for anime whose
// art lives only in the new poster system — /api/animes/:id answers with the
// missing-art asset while GraphQL's poster.originalUrl carries the real URL.
// The GraphQL leg (extras[2]) fills the namespace ONLY when the REST leg
// produced no poster; a real REST poster always wins; anything but a usable
// GraphQL answer leaves honest absence.
func TestConvertPosterGraphQLFallback(t *testing.T) {
	p := &sourceImpl{}
	const missingRest = `{"id": 60636, "name": "Bleach", "russian": "Бич", "kind": "tv",
		"status": "ongoing", "episodes": 10, "url": "/animes/60636-x",
		"image": {"original": "/assets/globals/missing_original.jpg"}}`
	const realRest = `{"id": 1, "name": "Air", "russian": "Воздух", "kind": "tv",
		"status": "released", "episodes": 13, "url": "/animes/1-air",
		"image": {"original": "/images/animes/1.jpg"}}`
	const gqlAnswer = `{"data":{"animes":[{"poster":{"originalUrl":"https://shikimori.io/uploads/poster/animes/60636/main-17c08aafd12c84275d13866fe655cf6d.webp"}}]}}`

	fetched := func(body string) *metadatav1.FetchedResponse {
		return &metadatav1.FetchedResponse{Body: []byte(body), Fetched: true}
	}

	cases := []struct {
		name      string
		payload   string
		extras    []*metadatav1.FetchedResponse
		want      string // want poster value; "" = want the key ABSENT
	}{
		{
			name:    "missing-art REST poster is filled from the GraphQL answer",
			payload: missingRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(gqlAnswer)},
			want:    "https://shikimori.io/uploads/poster/animes/60636/main-17c08aafd12c84275d13866fe655cf6d.webp",
		},
		{
			name:    "empty REST image is filled too",
			payload: `{"id": 2, "name": "NoImg", "kind": "tv", "url": "/animes/2-x"}`,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(`{"data":{"animes":[{"poster":{"originalUrl":"/uploads/poster/animes/2/a.jpeg"}}]}}`)},
			want:    "https://shikimori.io/uploads/poster/animes/2/a.jpeg",
		},
		{
			name:    "a real REST poster wins — the GraphQL answer is ignored",
			payload: realRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(gqlAnswer)},
			want:    "https://shikimori.io/images/animes/1.jpg",
		},
		{
			name:    "unfetched GraphQL leg leaves honest absence",
			payload: missingRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, {Error: "dial tcp: refused"}},
			want:    "",
		},
		{
			name:    "malformed GraphQL body leaves honest absence",
			payload: missingRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(`<!DOCTYPE html>`)},
			want:    "",
		},
		{
			name:    "empty animes list leaves honest absence",
			payload: missingRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(`{"data":{"animes":[]}}`)},
			want:    "",
		},
		{
			name:    "a GraphQL missing-art poster is dropped like the REST one",
			payload: missingRest,
			extras:  []*metadatav1.FetchedResponse{nil, nil, fetched(`{"data":{"animes":[{"poster":{"originalUrl":"/assets/globals/missing_original.jpg"}}]}}`)},
			want:    "",
		},
		{
			name:    "no extras at all (a search-shaped run) leaves honest absence",
			payload: missingRest,
			want:    "",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			req := convertReq(t, tc.payload, nil)
			req.ExtraResponses = tc.extras
			res, err := p.Convert(context.Background(), req)
			if err != nil {
				t.Fatalf("Convert: %v", err)
			}
			if res.GetError() != nil {
				t.Fatalf("Convert error: %v", res.GetError())
			}
			ns := res.GetMetadata().AsMap()
			if tc.want == "" {
				if _, ok := ns["poster"]; ok {
					t.Fatalf("poster = %v, want the key ABSENT (honest absence)", ns["poster"])
				}
				return
			}
			if got, _ := ns["poster"].(string); got != tc.want {
				t.Fatalf("poster = %v, want %q", ns["poster"], tc.want)
			}
		})
	}
}

// TestConvert drives Convert over the fixture payloads (box 1.3): the by-id
// single-object namespace shape, the multi-candidate selection (preference
// score + nothing-agrees determinism), the empty result, and the provenance
// hints.
func TestConvert(t *testing.T) {
	p := &sourceImpl{}

	t.Run("by-id payload fills the RU-first namespace", func(t *testing.T) {
		payload := `{
			"id": 1, "name": "Cowboy Bebop", "russian": "Ковбой Бибоп",
			"kind": "tv", "status": "released", "score": "8.542",
			"episodes": 26, "aired_on": "1998-04-03",
			"description": "В 2071 году...",
			"url": "/animes/1-cowboy-bebop",
			"image": {"original": "/images/anime/original/1.jpg"},
			"genre": [{"name": "Adventure", "russian": "Приключения"},
			          {"name": "Sci-Fi", "russian": "Фантастика"}]
		}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		title, _ := meta["title"].(map[string]any)
		if title["romaji"] != "Cowboy Bebop" || title["russian"] != "Ковбой Бибоп" {
			t.Errorf("title = %v, want {romaji, russian}", title)
		}
		for k, want := range map[string]any{
			"kind":        "tv",
			"status":      "released",
			"score":       8.542,
			"episodes":    float64(26),
			"aired_on":    "1998-04-03",
			"description": "В 2071 году...",
			"url":         "https://shikimori.io/animes/1-cowboy-bebop",
			"poster":      "https://shikimori.io/images/anime/original/1.jpg",
		} {
			if meta[k] != want {
				t.Errorf("meta[%q] = %v, want %v", k, meta[k], want)
			}
		}
		genres, _ := meta["genres"].([]any)
		if len(genres) != 2 || genres[0] != "Приключения" || genres[1] != "Фантастика" {
			t.Errorf("genres = %v, want the RU-first names", genres)
		}
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if ids[idKey] != float64(1) {
			t.Errorf("resolved_ids = %v, want {shikimori_id: 1}", ids)
		}
		for field, hint := range res.GetProvenance() {
			if hint.GetPluginId() != pluginID || hint.GetPluginVersion() != pluginVersion {
				t.Errorf("provenance[%q] = %s@%s, want %s@%s", field,
					hint.GetPluginId(), hint.GetPluginVersion(), pluginID, pluginVersion)
			}
			if hint.GetSourceUrl() != "https://shikimori.io/animes/1-cowboy-bebop" {
				t.Errorf("provenance[%q].source_url = %q, want the anime URL", field, hint.GetSourceUrl())
			}
		}
	})

	t.Run("multi-candidate search prefers year kind and episode agreement", func(t *testing.T) {
		payload := `[
			{"id": 10, "name": "Wrong Series", "kind": "tv", "episodes": 26, "aired_on": "1996-01-01"},
			{"id": 20, "name": "Perfect Blue", "russian": "Идеальная грусть", "kind": "movie",
			 "episodes": 1, "aired_on": "1997-08-05", "url": "/animes/20-perfect-blue"},
			{"id": 30, "name": "Other Movie", "kind": "movie", "episodes": 1, "aired_on": "1999-02-17"}
		]`
		query := map[string]any{"title": "Perfect Blue", "kind": "movie", "year": int64(1997), "episodes": int64(1)}
		res, err := p.Convert(context.Background(), convertReq(t, payload, query))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		meta := res.GetMetadata().AsMap()
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(20) {
			t.Fatalf("selected candidate id = %v, want 20 (year + kind + episodes agree)", got)
		}
		if got := res.GetMetadata().AsMap()["title"].(map[string]any)["romaji"]; got != "Perfect Blue" {
			t.Errorf("selected title.romaji = %q, want Perfect Blue", got)
		}
	})

	t.Run("nothing agreeing still selects deterministically without error", func(t *testing.T) {
		payload := `[
			{"id": 10, "name": "First", "kind": "tv", "episodes": 12, "aired_on": "2001-01-01"},
			{"id": 20, "name": "Second", "kind": "tv", "episodes": 24, "aired_on": "2002-01-01"}
		]`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"title": "First"}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("nothing-agrees selection errored: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(10) {
			t.Fatalf("selected candidate id = %v, want 10 (upstream order breaks ties)", got)
		}
	})

	t.Run("empty result list is a recorded soft error", func(t *testing.T) {
		res, err := p.Convert(context.Background(), convertReq(t, `[]`, map[string]any{"title": "Х"}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() == nil || res.GetError().GetCode() != "upstream_empty" {
			t.Fatalf("error = %v, want code upstream_empty", res.GetError())
		}
		if len(res.GetMetadata().GetFields()) != 0 {
			t.Errorf("metadata = %v, want empty on a soft error", res.GetMetadata().AsMap())
		}
	})

	t.Run("roles extra response composes the convention cast", func(t *testing.T) {
		req := convertReq(t, byIDPayload, nil)
		req.ExtraResponses = []*metadatav1.FetchedResponse{
			{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)},
		}
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		cast, ok := res.GetMetadata().AsMap()[castKey].([]any)
		if !ok || len(cast) != 4 {
			t.Fatalf("cast = %v (ok=%v), want 4 usable entries (the nameless entry skipped)", cast, ok)
		}
		e0, e1, e2, e3 := cast[0].(map[string]any), cast[1].(map[string]any), cast[2].(map[string]any), cast[3].(map[string]any)
		if e0["name"] != "Мисудзу Камио" || e0["role"] != "Асами Санада" ||
			e0["photo_url"] != "https://shikimori.io/images/characters/448.jpg" {
			t.Errorf("cast[0] = %v, want the russian character name, the seiyuu credit and the absolute portrait", e0)
		}
		if e1["name"] != "Юкито Кунисаки" || e1["role"] != nil {
			t.Errorf("cast[1] = %v, want no role when the character has no seiyuu credit", e1)
		}
		if e2["name"] != "Без Портрета" || e2["photo_url"] != nil || e2["role"] != nil {
			t.Errorf("cast[2] = %v, want the optional keys ABSENT when the upstream omits them", e2)
		}
		if e3["role"] != "Первый Сэйю, Second Va" {
			t.Errorf("cast[3].role = %v, want the comma-joined russian-preferred credits", e3["role"])
		}
		if _, has := res.GetProvenance()[castKey]; !has {
			t.Errorf("provenance carries no %q hint, want one like every namespace field", castKey)
		}
	})

	t.Run("missing unfetched or unusable roles leave cast absent", func(t *testing.T) {
		fetchedRoles := func(body string) []*metadatav1.FetchedResponse {
			return []*metadatav1.FetchedResponse{{Fetched: true, HttpStatus: 200, Body: []byte(body)}}
		}
		for _, tc := range []struct {
			name    string
			payload string
			extras  []*metadatav1.FetchedResponse
		}{
			{"no extra responses at all", byIDPayload, nil},
			{"soft-failed extra carries no body", byIDPayload,
				[]*metadatav1.FetchedResponse{{Fetched: false, Error: "connection refused"}}},
			{"empty roles array", byIDPayload, fetchedRoles(`[]`)},
			{"unparsable roles body", byIDPayload, fetchedRoles(`{"error":"not found"}`)},
			{"no usable entries", byIDPayload, fetchedRoles(`[{"seyu": [{"name": "X"}]}]`)},
			{"search list payload stays castless", listPayload, nil},
		} {
			t.Run(tc.name, func(t *testing.T) {
				req := convertReq(t, tc.payload, nil)
				req.ExtraResponses = tc.extras
				res, err := p.Convert(context.Background(), req)
				if err != nil {
					t.Fatalf("Convert: %v", err)
				}
				if got := res.GetError(); tc.payload == byIDPayload && got != nil {
					t.Fatalf("unexpected Convert error: %v", got)
				}
				meta := res.GetMetadata().AsMap()
				if cast, has := meta[castKey]; has {
					t.Errorf("meta[%q] = %v, want the field ABSENT (honest absence, never an empty array)", castKey, cast)
				}
			})
		}
	})
}

// TestConvertEpisodeTitles pins the episodes leg of Convert (box 1.3): the
// request plan's extras are positional and this plugin declares two —
// extras[0] the roles fetch (cast, unchanged), extras[1] the episodes fetch —
// so Convert maps the episodes body into per-episode EpisodeTitle entries:
// episode the served number, metadata exactly {"title": the russian name when
// the entry serves one, else the other served name} — NEVER a description.
// An unfetched extra, an unparsable body, or entries without usable names
// contribute NOTHING (honest absence); the series namespace mapping is
// untouched by the leg; a search payload (no anchor, no extras) produces no
// entries.
func TestConvertEpisodeTitles(t *testing.T) {
	p := &sourceImpl{}

	// The fixture pins the episodes payload shape: per-season entries in the
	// upstream's own name+russian convention (the one every other shikimori
	// object in this plugin decodes), russian-preferred with the other
	// served name the fallback. shikimori.io was unreachable this session
	// (522), so the live capture could not re-pin it; the contract holds
	// under either payload reality (design Risks) and the delta requirement
	// never names upstream fields.
	episodesPayload := `[
		{"id": 501, "anime_id": 1, "episode": 1, "name": "I Recant", "russian": "Зов крови", "description": "upstream text"},
		{"id": 502, "anime_id": 1, "episode": 2, "name": "Only Other Name"},
		{"id": 503, "anime_id": 1, "episode": 3, "russian": "Только Русское"},
		{"id": 504, "anime_id": 1, "episode": 4}
	]`
	fetchedEpisodes := func(body string) *metadatav1.FetchedResponse {
		return &metadatav1.FetchedResponse{Fetched: true, HttpStatus: 200, Body: []byte(body)}
	}

	t.Run("named entries convert ru-first keyed by episode number", func(t *testing.T) {
		req := convertReq(t, byIDPayload, nil)
		req.ExtraResponses = []*metadatav1.FetchedResponse{
			{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)}, // extras[0] stays the roles fetch
			fetchedEpisodes(episodesPayload),                             // extras[1] the episodes fetch
		}
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		titles := res.GetEpisodeTitles()
		if len(titles) != 3 {
			t.Fatalf("episode_titles = %d entries, want 3 (the nameless entry skipped)", len(titles))
		}
		want := []struct {
			episode int64
			title   any
		}{
			{1, "Зов крови"}, // russian wins over the other served name
			{2, "Only Other Name"},
			{3, "Только Русское"},
		}
		for i, w := range want {
			got := titles[i]
			if got.GetEpisode() != w.episode {
				t.Errorf("episode_titles[%d].episode = %d, want %d", i, got.GetEpisode(), w.episode)
			}
			meta := got.GetMetadata().AsMap()
			if len(meta) != 1 || meta["title"] != w.title {
				t.Errorf("episode_titles[%d].metadata = %v, want exactly {title: %v} (NEVER a description)", i, meta, w.title)
			}
		}
		// The series namespace mapping is untouched by the episodes leg.
		meta := res.GetMetadata().AsMap()
		if _, ok := meta["title"].(map[string]any); !ok {
			t.Errorf("meta[title] = %v, want the {romaji, russian} object unchanged", meta["title"])
		}
		if cast, has := meta[castKey].([]any); !has || len(cast) == 0 {
			t.Errorf("meta[%q] = %v, want the roles leg still composing the cast", castKey, meta[castKey])
		}
		if _, has := meta["episode_titles"]; has {
			t.Error("meta carries episode_titles, want per-episode data ONLY on the result field (D2)")
		}
	})

	t.Run("unfetched unparsable and nameless episodes contribute nothing", func(t *testing.T) {
		for _, tc := range []struct {
			name   string
			extras []*metadatav1.FetchedResponse
		}{
			{"no extra responses at all", nil},
			{"episodes extra soft-failed", []*metadatav1.FetchedResponse{
				{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)},
				{Fetched: false, Error: "connection refused"},
			}},
			{"unparsable episodes body", []*metadatav1.FetchedResponse{
				{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)},
				fetchedEpisodes(`{"error":"not found"}`),
			}},
			{"no usable entries", []*metadatav1.FetchedResponse{
				{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)},
				fetchedEpisodes(`[{"episode": 1}, {"episode": 2, "name": "", "russian": ""}]`),
			}},
		} {
			t.Run(tc.name, func(t *testing.T) {
				req := convertReq(t, byIDPayload, nil)
				req.ExtraResponses = tc.extras
				res, err := p.Convert(context.Background(), req)
				if err != nil {
					t.Fatalf("Convert: %v", err)
				}
				if got := res.GetError(); got != nil {
					t.Fatalf("unexpected Convert error: %v", got)
				}
				if titles := res.GetEpisodeTitles(); len(titles) != 0 {
					t.Errorf("episode_titles = %v, want NONE (honest absence — no empty entries, no placeholders)", titles)
				}
			})
		}
	})

	t.Run("search payload produces no entries", func(t *testing.T) {
		res, err := p.Convert(context.Background(), convertReq(t, listPayload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if titles := res.GetEpisodeTitles(); len(titles) != 0 {
			t.Errorf("episode_titles = %v, want none on a search run (single-fetch plan)", titles)
		}
		meta := res.GetMetadata().AsMap()
		if _, ok := meta["title"].(map[string]any); !ok {
			t.Errorf("meta[title] = %v, want the single-fetch namespace shape unchanged", meta["title"])
		}
	})
}

// TestMerge pins the namespace write (box 1.3): Merge writes ONLY
// sources["shikimori"], strips the reserved resolved_ids entry (core-side
// identifier input, never a namespace field), and binds every surviving field
// in the view proposal.
func TestMerge(t *testing.T) {
	p := &sourceImpl{}
	incoming, err := structpb.NewStruct(map[string]any{
		"title":        map[string]any{"romaji": "Cowboy Bebop", "russian": "Ковбой Бибоп"},
		"kind":         "tv",
		resolvedIDsKey: map[string]any{idKey: int64(1)},
	})
	if err != nil {
		t.Fatalf("fixture incoming struct: %v", err)
	}
	res, err := p.Merge(context.Background(), &metadatav1.MergeRequest{Incoming: incoming, PluginId: pluginID})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := res.GetDocument().GetData().AsMap()
	if len(data) != 1 {
		t.Fatalf("document top-level keys = %v, want exactly {sources} (INV-namespace-write)", data)
	}
	sources, _ := data["sources"].(map[string]any)
	ns, _ := sources[pluginID].(map[string]any)
	if _, has := ns[resolvedIDsKey]; has {
		t.Errorf("sources.%s carries reserved %s, want it stripped for doc.identifiers", pluginID, resolvedIDsKey)
	}
	if ns["kind"] != "tv" {
		t.Errorf("sources.%s.kind = %v, want tv", pluginID, ns["kind"])
	}
	for _, vb := range res.GetView() {
		if vb.GetSource() != pluginID {
			t.Errorf("view[%q].source = %q, want %q", vb.GetFieldPath(), vb.GetSource(), pluginID)
		}
	}
}

// TestConvertDropsMissingArt pins the write-side missing-art drop (artwork):
// the committed golden fixture internal/api/testdata/golden/missing_art.json
// drives BOTH predicates this plugin owns — the namespace poster and the cast
// photo_url. Every sample with plugin_drop=true must yield a namespace
// without the poster key (and cast entries without photo_url); samples with
// false pass through unchanged. The api walk-side test consumes the SAME
// fixture, so either side changing its predicate alone fails this suite.
func TestConvertDropsMissingArt(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "internal", "api", "testdata", "golden", "missing_art.json"))
	if err != nil {
		t.Fatalf("read golden fixture: %v", err)
	}
	var fixture struct {
		Samples []struct {
			URL        string `json:"url"`
			PluginDrop bool   `json:"plugin_drop"`
			WalkSkip   bool   `json:"walk_skip"`
		} `json:"samples"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("decode golden fixture: %v", err)
	}
	if len(fixture.Samples) < 3 {
		t.Fatalf("golden fixture carries %d samples, want >= 3", len(fixture.Samples))
	}
	for _, s := range fixture.Samples {
		// The poster leg: namespaceFields drops the key on a missing-art URL,
		// keeps it otherwise. absoluteURL runs first, so the relative-form
		// sample (an absolute check on a relative payload path) drops too.
		m := namespaceFields(animeEntry{ID: 1, Name: "Test", Image: animeImage{Original: s.URL}})
		_, hasPoster := m["poster"]
		if hasPoster == s.PluginDrop {
			t.Errorf("poster %q: key present = %v, want !plugin_drop(%v)", s.URL, hasPoster, !s.PluginDrop)
		}
		// The cast leg: the entry SURVIVES (its name is real data), the
		// photo_url field is the dropped one.
		body, err := json.Marshal([]rolesEntry{{Name: "Spike", Image: animeImage{Original: s.URL}}})
		if err != nil {
			t.Fatalf("marshal roles: %v", err)
		}
		cast := castField(body)
		if len(cast) != 1 {
			t.Fatalf("cast for %q: %d entries, want 1 (the entry survives the drop)", s.URL, len(cast))
		}
		entry, _ := cast[0].(map[string]any)
		_, hasPhoto := entry["photo_url"]
		if hasPhoto == s.PluginDrop {
			t.Errorf("cast photo_url %q: present = %v, want !plugin_drop(%v)", s.URL, hasPhoto, !s.PluginDrop)
		}
	}
}
